<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import { ElMessage } from 'element-plus'
import AppShell from '@/components/AppShell.vue'
import { createOutputTemplate,listOutputTemplates,listTemplateVersions,publishOutputTemplate,testOutputTemplate,type OutputTemplate,type TemplateVersion } from '@/api/templates'
const templates=ref<OutputTemplate[]>([]),versions=ref<TemplateVersion[]>([]),selectedId=ref(''),loading=ref(false),dialog=ref(false),file=ref<File>();
const selected=computed(()=>templates.value.find(item=>item.id===selectedId.value));
const form=reactive({templateCode:'',templateName:'',documentTypeCode:'请示',hasRedHeader:true,hasFooterMark:true,direction:'上行',description:''});
function fail(reason:unknown,fallback:string){ElMessage.error(reason instanceof Error?reason.message:fallback)}
async function load(){loading.value=true;try{templates.value=await listOutputTemplates();selectedId.value||=templates.value[0]?.id??''}catch(e){fail(e,'模板加载失败')}finally{loading.value=false}}
async function loadVersions(){versions.value=selectedId.value?await listTemplateVersions(selectedId.value):[]}
async function create(){if(!file.value){ElMessage.warning('请选择 DOCX 模板文件');return}try{const value=await createOutputTemplate(file.value,{...form});templates.value.unshift(value);selectedId.value=value.id;dialog.value=false;ElMessage.success('模板已上传并通过安全检查')}catch(e){fail(e,'模板上传失败')}}
async function test(){if(!selected.value)return;try{const blob=await testOutputTemplate(selected.value.id);const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${selected.value.templateCode}-test.docx`;link.click();URL.revokeObjectURL(url);await load();ElMessage.success('模拟填充通过，预览文件已生成')}catch(e){fail(e,'模拟填充失败')}}
async function publish(){if(!selected.value)return;try{const updated=await publishOutputTemplate(selected.value.id);const index=templates.value.findIndex(item=>item.id===updated.id);templates.value[index]=updated;await loadVersions();ElMessage.success('模板已发布生效')}catch(e){fail(e,'模板发布失败')}}
watch(selectedId,()=>loadVersions().catch(e=>fail(e,'版本加载失败')));onMounted(load)
</script>
<template><AppShell><template #title>输出模板中心</template><section class="template-center" v-loading="loading"><header class="template-hero"><div><span class="section-no">DOCX TEMPLATE GOVERNANCE</span><h2>版式不是最后补上的，<br><em>它从生成之前就被确定。</em></h2><p>模板文件、安全检查、占位符、模拟填充和发布版本统一治理。</p></div><button class="primary-button" type="button" @click="dialog=true">上传 DOCX 模板</button></header><div class="template-grid"><aside class="template-list"><header><span class="section-no">TEMPLATES</span><b>{{ templates.length }}</b></header><button v-for="item in templates" :key="item.id" type="button" :class="{active:item.id===selectedId}" @click="selectedId=item.id"><span>{{ item.documentTypeCode.slice(0,1) }}</span><div><strong>{{ item.templateName }}</strong><small>{{ item.templateCode }} · V{{ item.currentVersion }}</small></div><i :data-status="item.lifecycleStatus">{{ item.lifecycleStatus }}</i></button><div v-if="!templates.length" class="governance-empty">尚未上传输出模板。</div></aside><main v-if="selected" class="template-detail"><header><div><span class="section-no">{{ selected.direction || '通用' }} / {{ selected.documentTypeCode }}</span><h3>{{ selected.templateName }}</h3><p>{{ selected.description }}</p></div><b :data-status="selected.lifecycleStatus">{{ selected.lifecycleStatus }}</b></header><dl class="template-meta"><div><dt>当前版本</dt><dd>V{{ selected.currentVersion }}</dd></div><div><dt>红色版头</dt><dd>{{ selected.hasRedHeader?'包含':'不包含' }}</dd></div><div><dt>版记区域</dt><dd>{{ selected.hasFooterMark?'包含':'不包含' }}</dd></div><div><dt>文件指纹</dt><dd><code>{{ selected.templateFileHash.slice(0,12) }}…</code></dd></div></dl><section class="placeholder-sheet"><header><span class="section-no">PLACEHOLDER MAP / CLOB</span><h4>占位符映射</h4></header><div><article v-for="(meaning,key) in selected.placeholderMap" :key="key"><code>{{ key }}</code><span>{{ meaning }}</span></article></div></section><section class="template-versions"><header><span class="section-no">VERSION LEDGER</span><h4>版本记录</h4></header><article v-for="version in versions" :key="version.id"><b>V{{ version.versionNumber }}</b><div><strong>{{ version.changeNote }}</strong><small>{{ version.lifecycleStatus }} · {{ new Date(version.createdAt).toLocaleString('zh-CN',{hour12:false}) }}</small></div><span>{{ version.approvedBy || '待审批' }}</span></article></section><footer><button class="secondary-button" type="button" @click="test">模拟填充并下载</button><button v-if="selected.lifecycleStatus==='测试'" class="primary-button" type="button" @click="publish">发布生效</button><span v-else-if="selected.lifecycleStatus==='草稿'">请先完成模拟填充测试</span></footer></main><main v-else class="template-detail template-empty">上传一份 DOCX 模板开始治理。</main></div></section>
<el-dialog v-model="dialog" title="上传输出模板" width="620px" class="task-dialog"><el-form label-position="top"><div class="form-pair"><el-form-item label="模板代码"><el-input v-model="form.templateCode" /></el-form-item><el-form-item label="模板名称"><el-input v-model="form.templateName" /></el-form-item></div><div class="form-pair"><el-form-item label="适用文种"><el-input v-model="form.documentTypeCode" /></el-form-item><el-form-item label="行文方向"><el-select v-model="form.direction"><el-option v-for="v in ['上行','下行','平行','内部']" :key="v" :value="v" /></el-select></el-form-item></div><el-form-item label="DOCX 文件"><input type="file" accept=".docx" @change="file=($event.target as HTMLInputElement).files?.[0]" /></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" /></el-form-item><div class="form-pair"><el-checkbox v-model="form.hasRedHeader">包含红色版头</el-checkbox><el-checkbox v-model="form.hasFooterMark">包含版记区域</el-checkbox></div></el-form><template #footer><button class="secondary-button" type="button" @click="dialog=false">取消</button><button class="primary-button" type="button" @click="create">上传并检查</button></template></el-dialog></AppShell></template>
